var t=[{title:`Onderdelen van een barbell`,text:`Een gebruikelijke opstelling heeft een stang, schijven die erop passen en klemmen om de schijven zo nodig op hun plaats te houden. De lege stang kan voor een beginner zwaar aanvoelen, en speciale stangen hebben andere gewichten en maten. Noteer het totale gewicht dat je tilt, inclusief de stang, en niet alleen de schijven.`},{title:`Waarom een barbell gebruiken`,text:`Met kleine schijven kun je de belasting in nauwkeurige stappen verhogen, en één stang kan meerdere belangrijke bewegingspatronen trainen. Beide handen houden echter één vaste stang vast, en dat past niet bij elke schouder of pols. Dumbbells, machines of oefeningen met lichaamsgewicht zijn misschien een betere keuze als je uitrusting, comfort of ervaring beperkt is.`},{title:`Rek en veiligheid inrichten`,text:`Zet bij squats de J-hooks op de juiste hoogte voor jou en plaats de veiligheidsarmen of -pinnen zo dat ze een mislukte herhaling opvangen terwijl je nog door je volledige geplande bereik kunt bewegen. Gebruik bij de bankdruk een bekwame spotter of goed ingestelde veiligheidsstoppen. Oefen het in en uit het rek stappen met een lege stang voordat je zware gewichten tilt.`},{title:`Leer voordat je zwaarder gaat`,text:`Oefen de squat, hinge, pers of row met lichte weerstand tot de stang bij elke herhaling hetzelfde pad volgt. Zet je schijven vast als dat nodig is, controleer de ruimte om je heen en ga er nooit van uit dat een bank, standaard of geïmproviseerd rek een vallende stang kan opvangen. Als beginner hoef je je eenherhalingsmaximum niet te testen om kracht op te bouwen. Doe barbell-lifts alleen als je de juiste stang en schijven, een rek of andere veilige opstelling en genoeg ruimte hebt. Train je alleen zonder goede veiligheidsstoppen of heb je beperkingen bij het belasten van je wervelkolom, kies dan een andere oefening.`}];var i=[{label:`NSCA: basis van veiligheid en krachttraining`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`},{label:`Mayo Clinic: techniek bij krachttraining (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`},{label:`Standpunt van het ACSM uit 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var a={sections:t,sources:i};export{a as default,t as sections,i as sources};